const assert = require('assert');
const Module = require('module');
const { Timestamp } = require('firebase-admin/firestore');
// --- stub de firebase-admin (sin red) ---
const calls = { queryBounds: [], reportSets: {}, savedPaths: [] };
const fakeDb = {
  collection(name) {
    const filters = [];
    const q = {
      where(f, op, v) { filters.push([f, op, v]); return q; },
      async get() {
        if (name === 'clockRecords') {
          const lo = filters.find(x => x[1] === '>=')[2].toDate();
          const hi = filters.find(x => x[1] === '<=')[2].toDate();
          calls.queryBounds.push({ lo: lo.toISOString(), hi: hi.toISOString() });
          const recs = global.__RECORDS__.filter(r => r.clockIn.toDate() >= lo && r.clockIn.toDate() <= hi);
          return { docs: recs.map(r => ({ data: () => r })), forEach: fn => recs.forEach(r => fn({ data: () => r })) };
        }
        return { docs: [], forEach() {} };
      },
      doc(id) { return {
        async get() { return { exists: name === 'employees', data: () => ({ name: 'Ana', companyId: 'c1' }) }; },
        async set(p) { if (name === 'clockReports') calls.reportSets[id] = p; },
      }; },
    };
    return q;
  },
};
const fakeAdmin = { apps: [1], initializeApp() {}, firestore: Object.assign(() => fakeDb, { FieldValue: { serverTimestamp: () => 'TS' } }),
  storage: () => ({ bucket: () => ({ name: 'b', file: (p) => ({ async getMetadata() { throw 0; }, async save(buf) { calls.savedPaths.push(p); global.__PDF__ = buf; } }) }) }) };
const origLoad = Module._load;
Module._load = function (req, ...rest) {
  if (req === 'firebase-admin') return fakeAdmin;
  if (req.endsWith('notifications/sendPush')) return { sendPushToUsers: async () => {} };
  return origLoad.call(this, req, ...rest);
};
const reports = require('../../src/reports/monthlyReports');

describe('Informe de fichajes en Europe/Madrid', () => {
  it('un fichaje a las 00:30 del 1 de noviembre (Madrid) va al informe de noviembre', async () => {
    const rec = { companyId: 'c1', employeeId: 'e1', clockIn: Timestamp.fromDate(new Date('2026-10-31T23:30:00Z')), clockOut: Timestamp.fromDate(new Date('2026-11-01T07:30:00Z')) };
    global.__RECORDS__ = [rec];
    await reports.reportsOnClockRecordWrite.run({ data: { before: { exists: false }, after: { exists: true, data: () => rec } } });
