Future<void> _assertStackIsOnlyIndex(WidgetTester tester) async {
  expect(FirebaseAuth.instance.currentUser, isNull);
  expect(Get.currentRoute, Routes.index);
  final nav = Navigator.of(tester.element(find.text('ACCESO PARA FARMACIAS')));
  expect(nav.canPop(), isFalse, reason: 'Index no debe tener rutas autenticadas debajo');   // HOY falla
