  expect(byTypeName('CompanyMainPage'), findsNothing);   // HOY falla: vuelve al main
  expect(byTypeName('EmployeeMainPage'), findsNothing);  // HOY falla en el caso empleado
  expect(tester.takeException(), isNull);                // sin null-check de brain.*.value!
}

void main() {
  IntegrationTestWidgetsFlutterBinding.ensureInitialized();
  group('AUTH-SESSION-047 / EMPLOYEES-PROFILES-049', () {
    testWidgets('farmacia: logout desde Configuración deja la pila [index]', (tester) async {
      await launchApp(tester);
      await loginAsCompany(tester);
      await waitFor(tester, find.text('Perfil'), timeout: const Duration(seconds: 20));
      await _logoutFromSettings(tester);
      await _assertStackIsOnlyIndex(tester);
    });
    testWidgets('empleado: logout desde Configuración deja la pila [index]', (tester) async {
      await launchApp(tester);
      await loginAsEmployee(tester, email: Seed.<empleadoActivoEmail>);
      await waitFor(tester, find.text('Perfil'), timeout: const Duration(seconds: 20));
      await _logoutFromSettings(tester);
      await _assertStackIsOnlyIndex(tester);
    });
  });
}
