class CountingClockRepo implements ClockRepository {
  final List<ClockInOutModel> history; // 3000 turnos cerrados + 1 de hoy abierto
  int fullHistoryCalls = 0; int docsReturned = 0;
  CountingClockRepo(this.history);
  @override Future<Result<List<ClockInOutModel>>> getEntriesByEmployee(String id, {int? limit, DateTime? since}) async {
    fullHistoryCalls++;
    var r = history.where((e)=> since==null || !e.clockIn.isBefore(since)).toList()..sort((a,b)=>b.clockIn.compareTo(a.clockIn));
    if (limit!=null) r = r.take(limit).toList();
