    // Invariante 2: un único intento lógico del usuario => como mucho 1 documento.
    expect(docs.length, lessThanOrEqualTo(1), reason: 'duplicados: ${docs.length} (r2=$r2)');
    // Tras el fix: la escritura encolada se reporta como éxito/pending.
    expect(r1.success, isTrue);
