// Helper nuevo (mismo patrón que emulatorGetDoc): PATCH REST con 'Bearer owner'
Future<void> emulatorPatch(String path, Map<String, dynamic> restFields, List<String> mask) async {
  final uri = Uri.http('$emulatorHost:8080', '/v1/projects/farmatime-app/databases/(default)/documents/$path',
      {'updateMask.fieldPaths': mask});
  final c = HttpClient();
  final req = await c.patchUrl(uri);
  req.headers.set(HttpHeaders.authorizationHeader, 'Bearer owner');
  req.headers.contentType = ContentType.json;
  req.add(utf8.encode(json.encode({'fields': restFields})));
  final res = await req.close(); await res.drain(); c.close();
  expect(res.statusCode, 200);
}

void main() {
