void _goToTab(bool isCompany, int tabIndex) {
  final mainRoute = isCompany ? Routes.companyMain : Routes.employeeMain;
  final mainReady = isCompany
      ? Get.isRegistered<CompanyMainController>()
      : Get.isRegistered<EmployeeMainController>();
  if (!mainReady) { // arranque en frío / sesión recién iniciada
    Get.offAllNamed(mainRoute);
    isCompany
        ? _selectTabWhenReady<CompanyMainController>((c) => c.indexTab.value = tabIndex)
