class _SlowUpsert extends UpsertEmployeeMonthScheduleUseCase {
  _SlowUpsert() : super(_NoRepo());
  final calls = <String, Map<String, DayEntry>>{};   // mk -> entries enviadas
  final gates = <Completer<Result<bool>>>[];
  @override
  Future<Result<bool>> call({required String companyId, required String employeeId,
      required int year, required int month, required Map<String, DayEntry> entries}) {
    calls['$year-${month.toString().padLeft(2, '0')}'] = Map.of(entries);
    final c = Completer<Result<bool>>(); gates.add(c); return c.future;
  }
}

void main() {
  testWidgets('ediciones durante save() no se pierden', (tester) async {
    await tester.pumpWidget(ToastificationWrapper(child: GetMaterialApp(home: SizedBox())));
    Get.put<Brain>(Brain());
    Brain().company.value = CompanyModel.fromJson({'id': 'c1', /* campos mínimos */});
    final upsert = _SlowUpsert();
    final c = EmployeeScheduleController(           // sin Get.put → no corre onInit/loadAll
      getMonthUC: GetEmployeeMonthScheduleUseCase(_NoRepo()),
      upsertMonthUC: upsert,
      listRulesUC: ListRecurringRulesUseCase(_NoRepo()),
      getAssignedDaysUC: GetAssignedDaysInYearUseCase(_NoRepo()),
    );

    c.selectSingleDay(DateTime(2026, 10, 5));
    await c.setForSelection(DayEntry(type: DayType.vacation));
    expect(c.dirtyMonths, {'2026-10'});

    final saving = c.save();                 // queda bloqueado en el await del upsert
    await tester.pump();
    expect(c.isSaving.value, isTrue);
    expect(upsert.calls.keys, ['2026-10']);

    // Ediciones DURANTE el guardado
    c.selectSingleDay(DateTime(2026, 11, 3));
    await c.setForSelection(DayEntry(type: DayType.off));     // mes nuevo
    c.selectSingleDay(DateTime(2026, 10, 6));
    await c.setForSelection(DayEntry(type: DayType.off));     // mes ya enviado

    upsert.gates.single.complete(Result(success: true, data: true));
    await saving;            // loadBalances retorna pronto (employeeId '' no está en companyEmployees)
    await tester.pump(const Duration(seconds: 7));             // deja caducar el toast

    // HOY FALLA: dirtyMonths quedó vacío
    expect(c.hasUnsavedChanges, isTrue);
    expect(c.dirtyMonths, containsAll(['2026-10', '2026-11']));
    // Confirma que esas ediciones no llegaron a enviarse
    expect(upsert.calls['2026-10']!.containsKey('2026-10-06'), isFalse);
    expect(upsert.calls.containsKey('2026-11'), isFalse);
  });
}
