void main() {
  IntegrationTestWidgetsFlutterBinding.ensureInitialized();
  testWidgets('CLOCK-EDIT-RACE la edición de la farmacia no borra una salida concurrente', (tester) async {
    await launchApp(tester); // inicializa Firebase apuntando al emulador
    final db = FirebaseFirestore.instance;
    final id = const Uuid().v4();
    final clockIn = DateTime.now().subtract(const Duration(hours: 5));

    // 1) El empleado (Ana) ficha la entrada.
    await FirebaseAuth.instance.signInWithEmailAndPassword(email: Seed.empAnaEmail, password: Seed.password);
    final open = ClockInOutModel(id: id, companyId: 'qa-company-paid', employeeId: 'qa-emp-ana',
        clockIn: clockIn, isEdited: false, createdAt: clockIn, updatedAt: clockIn /* resto de campos requeridos */);
    await db.collection('clockRecords').doc(id).set(open.toJson());

    // 2) La farmacia "abre el editor": captura el modelo actual (clockOut == null).
    final stale = ClockInOutModel.fromJson((await db.collection('clockRecords').doc(id).get()).data()!);

    // 3) El empleado ficha la salida mientras tanto (mismo código que _doClockOut).
    final out = DateTime.now().subtract(const Duration(minutes: 1));
    await db.collection('clockRecords').doc(id).update(
        stale.copyWith(clockOut: out, clockOutLat: 40.41, clockOutLng: -3.70, updatedAt: out).toJson());
    await FirebaseAuth.instance.signOut();

    // 4) La farmacia guarda un cambio SOLO de la entrada (igual que EditEntryController.onSave).
    await FirebaseAuth.instance.signInWithEmailAndPassword(email: Seed.companyEmail, password: Seed.password);
    final newIn = clockIn.subtract(const Duration(minutes: 5));
    final now = DateTime.now();
    final edited = stale.copyWith(clockIn: newIn, clockOut: stale.clockOut, isEdited: true, editedBy: 'company',
        editedAt: now, editReason: 'olvido', editedFields: ['clockIn'], updatedAt: now);
    final log = ClockAuditLogModel(id: const Uuid().v4(), entryId: id, companyId: 'qa-company-paid',
        employeeId: 'qa-emp-ana', action: ClockAuditAction.edited, actorUid: 'qa-company-paid', actorRole: 'company',
        reason: 'olvido', changes: [ClockAuditChange(field: 'clockIn', oldValue: clockIn, newValue: newIn)], at: now);
    final res = await ClockRepositoryImpl().updateEntryWithAudit(entry: edited, auditLog: log);

    // 5) Aserciones (leer con bypass de reglas).
    final doc = restFields((await emulatorGetDoc('clockRecords/$id'))!);
    // Tras el fix A, res.success == false (conflicto) y el doc conserva la salida.
    // Tras el fix B, res.success == true y el doc conserva la salida con la nueva entrada.
    // HOY falla: clockOut == null y clockOutLat == null.
    expect(doc['clockOut'], isNotNull, reason: 'la salida concurrente del empleado no debe borrarse');
    expect(doc['clockOutLat'], isNotNull);
    if (res.success) {
      final logs = (await emulatorListDocs('clockRecords/$id/auditLog')).map(restFields).toList();
      // No puede quedar un log que omita un cambio real de clockOut.
      expect(logs.every((l) => (l['changes'] as List).every((c) => c['field'] != 'clockOut' || c['newValue'] != null)), isTrue);
    }
  });
}
