/// Decorador que cuenta documentos devueltos (= lecturas facturadas) por el repo.
class CountingClockRepository implements ClockRepository {
  CountingClockRepository(this._inner);
  final ClockRepositoryImpl _inner;
  int docsRead = 0;
  @override
  Future<Result<List<ClockInOutModel>>> getEntriesByEmployee(String id) async {
    final r = await _inner.getEntriesByEmployee(id);
    docsRead += r.data.length;
    return r;
  }
  @override
  Future<Result<ClockInOutModel?>> getCurrentEntry(String id) async {
    final r = await _inner.getCurrentEntry(id);
    docsRead += r.data == null ? 0 : 1;
    return r;
  }
  // Delegar el resto de métodos del interfaz (createEntry, updateEntry,
  // updateEntryWithAudit, logCreation, getAuditLog...) sin contar; tras el fix,
  // contar también getEntriesByEmployeeInRange igual que getEntriesByEmployee.
  @override
  dynamic noSuchMethod(Invocation i) => Function.apply(
      (_inner as dynamic).noSuchMethod, [i]); // o delegación explícita
}

void main() {
  IntegrationTestWidgetsFlutterBinding.ensureInitialized();
  testWidgets('PERF-READS-001 Mi día no descarga el histórico completo', (tester) async {
    await launchApp(tester);
    expect((await clockRecordsOf('qa-emp-luis')).length, greaterThanOrEqualTo(1000),
        reason: 'sembrar con --big');
    // Registrar ANTES del login: los bindings usan Get.lazyPut<ClockRepository>,
    // que no sustituye una instancia ya registrada.
    final counter = CountingClockRepository(ClockRepositoryImpl());
    Get.put<ClockRepository>(counter, permanent: true);

    await loginAsEmployee(tester, email: Seed.empLuisEmail);
    await waitFor(tester, find.text('FICHAR ENTRADA'), timeout: const Duration(seconds: 60));

    // Hoy Luis no tiene fichajes abiertos ni de hoy: el mínimo necesario es ~0-2 docs.
    expect(counter.docsRead, lessThanOrEqualTo(10),
        reason: 'Mi día leyó ${counter.docsRead} docs para mostrar solo el fichaje de hoy');
    Get.delete<ClockRepository>(force: true);
    await logoutEmployee(tester);
  });
}
```

