const crypto = require('crypto');
const { execFileSync } = require('child_process');
const fs = require('fs'); const os = require('os'); const path = require('path');
const { CompactSign, importPKCS8 } = require('jose');
const mod = require('../../src/iap/helpers/verifyAppleJws');

// PKI EC efímera con openssl; extsLeaf/extsInt permiten añadir los OID de Apple.
function makeChain({ leafOid, intOid }) {
  const d = fs.mkdtempSync(path.join(os.tmpdir(), 'pki-'));
  const sh = (...a) => execFileSync('openssl', a, { cwd: d, stdio: 'pipe' });
  for (const k of ['root', 'int', 'leaf']) sh('ecparam', '-name', 'prime256v1', '-genkey', '-noout', '-out', `${k}.key`);
  sh('req', '-x509', '-new', '-key', 'root.key', '-subj', '/CN=Test Root', '-days', '2', '-out', 'root.pem', '-addext', 'basicConstraints=critical,CA:true');
  fs.writeFileSync(path.join(d, 'int.ext'), `basicConstraints=critical,CA:true\nkeyUsage=critical,keyCertSign\n${intOid ? '1.2.840.113635.100.6.2.1=ASN1:NULL\n' : ''}`);
  fs.writeFileSync(path.join(d, 'leaf.ext'), leafOid ? '1.2.840.113635.100.6.11.1=ASN1:NULL\n' : 'basicConstraints=CA:false\n');
  sh('req', '-new', '-key', 'int.key', '-subj', '/CN=Test Int', '-out', 'int.csr');
  sh('x509', '-req', '-in', 'int.csr', '-CA', 'root.pem', '-CAkey', 'root.key', '-CAcreateserial', '-days', '2', '-extfile', 'int.ext', '-out', 'int.pem');
  sh('req', '-new', '-key', 'leaf.key', '-subj', '/CN=Apple Pay Payment Processing', '-out', 'leaf.csr');
  sh('x509', '-req', '-in', 'leaf.csr', '-CA', 'int.pem', '-CAkey', 'int.key', '-CAcreateserial', '-days', '2', '-extfile', 'leaf.ext', '-out', 'leaf.pem');
  const der = (f) => new crypto.X509Certificate(fs.readFileSync(path.join(d, f))).raw;
  return { x5c: ['leaf.pem', 'int.pem', 'root.pem'].map((f) => der(f).toString('base64')), rootDer: der('root.pem'),
           leafKey: crypto.createPrivateKey(fs.readFileSync(path.join(d, 'leaf.key'))).export({ type: 'pkcs8', format: 'pem' }) };
}
async function sign(chain, payload) {
  const key = await importPKCS8(chain.leafKey, 'ES256');
  return new CompactSign(Buffer.from(JSON.stringify(payload))).setProtectedHeader({ alg: 'ES256', x5c: chain.x5c }).sign(key);
}
// Hace que la raíz de prueba "sea" la G3: solo intercepta el hash del DER de esa raíz.
function pinRoot(rootDer) {
