  it('ACEPTA una cadena con ambos OID (control positivo, pasa hoy y tras el fix)', async () => {
    const chain = makeChain({ leafOid: true, intOid: true });
    const restore = pinRoot(chain.rootDer);
    try { const p = await mod.verifyAppleJws(await sign(chain, forgedTx)); assert.strictEqual(p.productId, 'plan_20'); }
