```dart
import 'package:firebase_auth/firebase_auth.dart';
import 'package:firebase_messaging/firebase_messaging.dart';
import 'package:flutter_test/flutter_test.dart';
import 'package:integration_test/integration_test.dart';
import 'helpers/qa_harness.dart';

void main() {
  IntegrationTestWidgetsFlutterBinding.ensureInitialized();

  testWidgets('logout borra el token FCM de A antes de que entre B', (tester) async {
    await launchApp(tester);
    await loginAsEmployee(tester, email: Seed.empAnaEmail);
    await waitFor(tester, find.text('Perfil'), timeout: const Duration(seconds: 20));
    final uidA = FirebaseAuth.instance.currentUser!.uid;
    final tokenA = await FirebaseMessaging.instance.getToken();
    if (tokenA == null) { markTestSkipped('sin token FCM en este dispositivo'); return; }

    // Precondición: el token de A está registrado (bypass de reglas, Bearer owner).
    await pumpUntil(tester, () async =>
        (await emulatorListDocs('user_fcm_tokens/$uidA/tokens')).isNotEmpty);

    await logoutEmployee(tester);                       // UI real: clearSession + signOut
    await pumpFor(tester, const Duration(seconds: 5));  // margen generoso para el ack

    // HOY FALLA: el doc sigue ahí (delete colgado en la cola de A).
    final docsA = await emulatorListDocs('user_fcm_tokens/$uidA/tokens');
    expect(docsA.where((d) => (d['name'] as String).endsWith('/$tokenA')), isEmpty,
        reason: 'el token del usuario saliente debe borrarse en Firestore');

    await loginAsEmployee(tester, email: Seed.empLuisEmail);
    await waitFor(tester, find.text('Perfil'), timeout: const Duration(seconds: 20));
    final uidB = FirebaseAuth.instance.currentUser!.uid;
    final tokenB = await FirebaseMessaging.instance.getToken();

    // HOY FALLA: deleteToken() nunca se ejecutó, así que el token no ha rotado.
    expect(tokenB, isNot(equals(tokenA)), reason: 'el token local debe rotarse al cerrar sesión');

    // Ningún token de este dispositivo puede pertenecer a la vez a A y a B.
    final namesA = (await emulatorListDocs('user_fcm_tokens/$uidA/tokens'))
        .map((d) => (d['name'] as String).split('/').last).toSet();
    final namesB = (await emulatorListDocs('user_fcm_tokens/$uidB/tokens'))
        .map((d) => (d['name'] as String).split('/').last).toSet();
    expect(namesA.intersection(namesB), isEmpty);

    await logoutEmployee(tester);
  });
}
```

`pumpUntil` es un helper pequeño: un bucle con pumpFor de 500 ms y un timeout de 15 s.

Variante determinista para hacerla sin carrera, de modo que falle siempre hoy: antes de `logoutEmployee`, desactivar la red de Firestore con `await FirebaseFirestore.instance.disableNetwork();` y reactivarla tras el logout con `enableNetwork()`. El delete se queda en cola, y la aserción `tokenB != tokenA` falla hoy y pasa con el fix (deleteToken de FCM ya no depende del ack).

